// Data-URI placeholders for the a11y fixtures page ONLY.
//
// They must be data URIs, not paths under static/dev/, because MediaText,
// SectionGrid and Testimonial render through <PrismicImage>, whose
// asImageWidthSrcSet calls new URL(url) — that throws on a relative path
// ("TypeError: Invalid URL") and 500s the prerender. A data URI parses as an
// absolute URL, and the CSP already allows data: under img-src.
//
// Slices using the starter's own HeroBackgroundImage (Hero, HeartHero) are
// tolerant of relative paths and read straight from static/dev/ instead.
export const PLACEHOLDER_HERO =
  "data:image/webp;base64,";

export const PLACEHOLDER_PORTRAIT =
  "data:image/webp;base64,";
